# Generated by Selenium IDE
from selenium import webdriver
from selenium.webdriver.common.by import By
from selenium.webdriver.support import expected_conditions as EC
from selenium.webdriver.support.wait import WebDriverWait



class TestBiblioteca():
  URL = "http://127.0.0.1:5000"

  def setup_method(self):
    self.driver = webdriver.Chrome()
    self.driver.maximize_window()
    self.wait = WebDriverWait(self.driver, 15)

  def teardown_method(self):
    self.driver.quit()

  def clicar(self, by, value):
    self.wait.until(
      EC.element_to_be_clickable((by, value))
    ).click()

  def digitar(self, by, value, texto):
    campo = self.wait.until(
      EC.visibility_of_element_located((by, value))
    )
    campo.clear()
    campo.send_keys(texto)

  def esperar_texto(self, seletor, texto):
    self.wait.until(
      EC.text_to_be_present_in_element(
        (By.CSS_SELECTOR, seletor),
        texto
      )
    )

  def test_cT001SenhaFraca(self):
    self.driver.get(self.URL)

    self.clicar(By.LINK_TEXT, "👤 Cadastrar Usuário")

    self.digitar(By.ID, "nome", "Lais")
    self.digitar(By.ID, "email", "laisrscurso@gmail.com")
    self.digitar(By.ID, "senha", "lais123")

    self.clicar(By.CSS_SELECTOR, "button[type='submit']")

    self.esperar_texto(
      ".flash",
      "Senha fraca: use letras, números e mínimo 8 caracteres"
    )

